package vn.vinhkhang.warehouse;
import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
@RestController @RequestMapping("/api/account") public class Accounts {
 private record Attempts(long until,int count){} private final Map<String,Attempts> attempts=new java.util.concurrent.ConcurrentHashMap<>();
 synchronized void throttle(String name){long now=System.currentTimeMillis();attempts.entrySet().removeIf(e->e.getValue().until()<now);var a=attempts.get(name);if(a!=null&&a.count()>=10)throw new Api.Problem(429,"Thử khôi phục quá nhiều lần. Anh thử lại sau 15 phút.");attempts.put(name,new Attempts(a==null?now+900000:a.until(),a==null?1:a.count()+1));}
 private final Api core;private final JdbcTemplate db;private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder();
 public Accounts(Api core,JdbcTemplate db){this.core=core;this.db=db;}
 static String fresh(){byte[] b=new byte[24];new SecureRandom().nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}
 static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 static void validate(String pw){if(pw==null||pw.length()<1||pw.getBytes(StandardCharsets.UTF_8).length>72)throw new Api.Problem(400,"Mật khẩu cần ít nhất 1 ký tự và tối đa 72 byte");}
 static void bootstrap(JdbcTemplate db){for(var row:db.queryForList("SELECT id FROM app_users u WHERE role='ADMIN' AND active=TRUE AND NOT EXISTS(SELECT 1 FROM recovery_secrets r WHERE r.user_id=u.id)")){long id=((Number)row.get("ID")).longValue();String code=fresh();try{Path file=Path.of(System.getenv().getOrDefault("VK_DATA_DIR","./data"),"recovery-admin-"+id+".txt");Files.createDirectories(file.getParent());Files.writeString(file,"Mã khôi phục quản trị Vĩnh Khang (dùng một lần):\n"+code+"\nCất riêng ở nơi an toàn. Không gửi cho người khác.\n",StandardOpenOption.CREATE_NEW);db.update("INSERT INTO recovery_secrets(user_id,code_hash) VALUES(?,?)",id,hash(code));}catch(Exception e){throw new IllegalStateException("Không lưu được mã khôi phục quản trị",e);}}}
 void current(long id,String pw){var rows=db.queryForList("SELECT password_hash FROM app_users WHERE id=? AND active=TRUE FOR UPDATE",id);if(rows.isEmpty()||pw==null||!encoder.matches(pw,(String)rows.getFirst().get("PASSWORD_HASH")))throw new Api.Problem(400,"Mật khẩu hiện tại không đúng");}
 @PostMapping("/change") @Transactional public void change(@RequestHeader("Authorization") String t,@RequestBody Map<String,Object> m){var s=core.user(t,false);current(s.id(),Objects.toString(m.get("current_password"),""));String pw=Objects.toString(m.get("new_password"),"");validate(pw);db.update("UPDATE app_users SET password_hash=? WHERE id=?",encoder.encode(pw),s.id());core.audit(s,"CHANGE_PASSWORD","users",s.id());core.invalidateSessions(s.id());}
 @PostMapping("/recovery-code") @Transactional public Map<String,String> generate(@RequestHeader("Authorization") String t,@RequestBody Map<String,Object> m){var s=core.user(t,false);current(s.id(),Objects.toString(m.get("current_password"),""));String code=fresh();db.update("MERGE INTO recovery_secrets(user_id,code_hash,used_at,created_at) KEY(user_id) VALUES(?,?,NULL,CURRENT_TIMESTAMP)",s.id(),hash(code));core.audit(s,"RECOVERY_CODE","users",s.id());return Map.of("code",code);}
 @PostMapping("/admin-reset/{id}") @Transactional public void adminReset(@RequestHeader("Authorization") String t,@PathVariable long id,@RequestBody Map<String,Object> m){var s=core.admin(t);if(id==s.id())throw new Api.Problem(400,"Đổi mật khẩu của anh bằng chức năng Đổi mật khẩu");if(db.queryForList("SELECT id FROM app_users WHERE id=? AND active=TRUE FOR UPDATE",id).isEmpty())throw new Api.Problem(404,"Không tìm thấy tài khoản");String pw=Objects.toString(m.get("new_password"),"");validate(pw);db.update("UPDATE app_users SET password_hash=? WHERE id=?",encoder.encode(pw),id);db.update("UPDATE recovery_secrets SET used_at=CURRENT_TIMESTAMP WHERE user_id=?",id);core.audit(s,"RESET_PASSWORD","users",id);core.invalidateSessions(id);}
 @PostMapping("/reset") @Transactional public void reset(@RequestBody Map<String,Object> m){String name=Objects.toString(m.get("username"),"");throttle(name);String code=Objects.toString(m.get("recovery_code"),"").trim();var rs=db.queryForList("SELECT u.id,r.code_hash,r.used_at FROM app_users u JOIN recovery_secrets r ON r.user_id=u.id WHERE u.username=? AND u.active=TRUE FOR UPDATE",name);if(rs.isEmpty()||rs.getFirst().get("USED_AT")!=null||!MessageDigest.isEqual(hash(code).getBytes(StandardCharsets.UTF_8),Objects.toString(rs.getFirst().get("CODE_HASH")).getBytes(StandardCharsets.UTF_8)))throw new Api.Problem(400,"Tên đăng nhập hoặc mã khôi phục không đúng / mã đã dùng");String pw=Objects.toString(m.get("new_password"),"");validate(pw);long id=((Number)rs.getFirst().get("ID")).longValue();db.update("UPDATE app_users SET password_hash=? WHERE id=?",encoder.encode(pw),id);db.update("UPDATE recovery_secrets SET used_at=CURRENT_TIMESTAMP WHERE user_id=?",id);core.audit(new Api.Session(id,name,"",java.time.Instant.now()),"RESET_PASSWORD","users",id);core.invalidateSessions(id);}
}
